functions.adjacent_left:
static color adjacent_left(color rotating_face, color around)
{
    color l_around = ((around + 5) % 6);
    if (l_around == ((rotating_face + 3) % 6) || l_around == rotating_face)
    {
        return ((l_around + 5) % 6);
    }
    return l_around;
}

functions.adjacent_right:
static color adjacent_right(color rotating_face, color around)
{
    color r_around = ((around + 1) % 6);
    if (r_around == ((rotating_face + 3) % 6) || r_around == rotating_face)
    {
        return ((r_around + 1) % 6);
    }
    return r_around;
}

