functions.populate_initial:
cube_t populate_initial()
{
    cube_t cube = (color **)(malloc(sizeof(color *) * 6));
    for (color face = RED; face <= WHITE; face++)
    {
        cube[face] = (color *)(malloc(sizeof(color) * 8));
        for (int pos = 0; pos < 8; pos++)
        {
            cube[face][pos] = face;
        }
    }
    return cube;
}

