functions.print_cube:
void print_cube(const cube_t cube)
{
    for (color face = RED; face <= WHITE; face++)
    {
        printf("%c %c %c\n%c %c %c\n%c %c %c\n", color_code[cube[face][0]], color_code[cube[face][1]],
               color_code[cube[face][2]], color_code[cube[face][7]], color_code[face], color_code[cube[face][3]],
               color_code[cube[face][6]], color_code[cube[face][5]], color_code[cube[face][4]]);
        printf("-----\n");
    }
}

functions.cube_compare_equal:
bool cube_compare_equal(const cube_t cube1, const cube_t cube2)
{
    for (color face = RED; face <= WHITE; face++)
    {
        for (int pos = 0; pos < 8; pos++)
        {
            if (cube1[face][pos] != cube2[face][pos])
            {
                return false;
            }
        }
    }
    return true;
}

functions.find_entropy:
int find_entropy(const cube_t cube)
{
    int count = 0;
    for (color face = RED; face <= WHITE; face++)
    {
        for (int pos = 0; pos < 8; pos++)
        {
            if (cube[face][pos] != face)
                count++;
        }
    }
    return count;
}

